import type {
  AlarmRecord,
  ControlBatch,
  ControlCommandType,
  DeviceEntity,
  SpatialTree,
  UserSession,
  WorkOrderRecord,
} from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';
import { bindSpacePathControl, getGlobalSpaceScope, renderSpacePathControl, setGlobalSpaceScope } from '../../app/space-context';
import { renderIcon } from '../../design-system/icons';

type ActiveTab = 'devices' | 'zones' | 'alarms';
type TopologyMode =
  | 'multi-project'
  | 'single-project-multi-building'
  | 'single-building'
  | 'floors-only';

type HomeScope =
  | { level: 'all-projects' }
  | { level: 'project'; projectId: string }
  | { level: 'building'; projectId: string; buildingId: string }
  | { level: 'floor'; projectId: string; buildingId: string; floorId: string };

function formatPinLabel(d: DeviceEntity): string {
  if (d.connectivity === 'offline') {
    const short = d.name.includes('VAV') ? 'VAV-02' : d.name.slice(0, 6);
    return `${short} 离线`;
  }
  if (d.category === 'lighting') {
    const short = d.name.includes('702') ? '702 照明' : '主照明';
    const dim = Number(d.telemetry.dimming?.value ?? 0);
    return dim > 0 ? `${short} ${dim}%` : `${short} 关`;
  }
  if (d.category === 'hvac') {
    const short = d.name.includes('VAV') ? 'VAV-02' : 'FCU-01';
    return `${short} ${d.telemetry.setpoint?.value ?? 24}°C`;
  }
  if (d.category === 'sensor') {
    return `环境 ${d.telemetry.temp?.value ?? '23.4'}°C`;
  }
  if (d.category === 'gateway') {
    return '主控网关';
  }
  return d.name.slice(0, 6);
}

const CATEGORY_LABELS: Record<DeviceEntity['category'], string> = {
  gateway: '网关',
  lighting: '照明',
  hvac: '暖通空调',
  sensor: '环境传感',
  meter: '计量表',
};

const RECEIPT_LABELS: Record<string, { text: string; badge: string }> = {
  queued: { text: '已排队', badge: 'pacom-badge--neutral' },
  dispatched: { text: '已下发网关', badge: 'pacom-badge--accent' },
  verified_success: { text: '回读已确认', badge: 'pacom-badge--online' },
  timeout: { text: '回读超时', badge: 'pacom-badge--critical' },
  rejected: { text: '设备拒绝', badge: 'pacom-badge--warning' },
  failed: { text: '执行失败', badge: 'pacom-badge--critical' },
};

const CHEVRON_DOWN_SVG = renderIcon('chevron-down', 12);

/** E7F 平面图功能区热区坐标（百分比定位，与 7F.webp 空间分区对齐） */
const E7F_ZONE_BOXES: Record<string, { left: number; top: number; width: number; height: number }> = {
  'zone-e7f-lab-east': { left: 56, top: 20, width: 34, height: 54 },
  'zone-e7f-meeting-702': { left: 14, top: 22, width: 28, height: 28 },
  'zone-e7f-office-west': { left: 12, top: 54, width: 32, height: 30 },
  'zone-e7f-corridor': { left: 41, top: 38, width: 15, height: 26 },
};

function escapeHtml(value: unknown): string {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function parseFloorOrder(name: string): number {
  const m = name.match(/(-?\d+)/);
  if (!m) return 0;
  const n = Number(m[1]);
  return name.toUpperCase().startsWith('B') ? -Math.abs(n) : n;
}

export async function mountE7FWorkspace(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession
): Promise<void> {
  const tree: SpatialTree = await adapter.getSpatialTree();
  const isDemo = adapter.mode === 'demo';
  const canControl = session.scope.canControlDevices;
  const canManageAlarms = session.scope.canManageAlarms;
  const memberZoneLimit = session.scope.allowedZoneIds?.length ? session.scope.allowedZoneIds : null;

  // 4 种客户拓扑自适应折叠（多园区 / 单园区多栋 / 单栋多层 / 几层或仅 1 层）
  const allowedFloors = tree.floors.filter((f) => session.scope.allowedFloorIds.includes(f.id));
  const topology: TopologyMode =
    memberZoneLimit || (tree.projects.length <= 1 && tree.buildings.length <= 1 && allowedFloors.length <= 1)
      ? 'floors-only'
      : tree.projects.length > 1
        ? 'multi-project'
        : tree.buildings.length > 1
          ? 'single-project-multi-building'
          : 'single-building';

  const canViewAllProjects = topology === 'multi-project';
  const canViewProject = topology === 'multi-project' || topology === 'single-project-multi-building';
  const canViewBuilding = topology !== 'floors-only';
  const isSingleFloorOnly = topology === 'floors-only' && allowedFloors.length <= 1;

  let scope: HomeScope = getGlobalSpaceScope();
  let activeTab: ActiveTab = 'devices';
  let hudOpen = false;
  let spacePopOpen = false;
  let spaceSearch = '';
  let searchKeyword = '';
  let categoryFilter = 'all';
  let zoneFilter = 'all';
  const hashQuery = new URLSearchParams(window.location.hash.split('?')[1] ?? '');
  const initDeviceId = hashQuery.get('device');
  const initZoneId = hashQuery.get('zone');
  let selectedDeviceId: string | null = initDeviceId;
  let drawerOpen = Boolean(initDeviceId);
  let drawerTab: 'control' | 'trend' | 'profile' = 'control';
  let drawerDocNotice = '';
  let briefingOpen = false;
  let briefingPeriod: 'today' | 'week' = 'today';
  let canvasLayer: 'devices' | 'temp' | 'occupancy' = 'devices';
  const overriddenDeviceIds = new Set<string>();
  const checkedDeviceIds = new Set<string>();
  let devices: DeviceEntity[] = [];
  let alarms: AlarmRecord[] = [];
  let workOrders: WorkOrderRecord[] = [];
  let activeBatch: ControlBatch | null = null;
  let floorError: string | null = null;
  let zoom = 1;
  let panX = 0;
  let panY = 0;

  let unsubscribe: (() => void) | null = null;

  function visibleZones() {
    return tree.zones.filter((z) => {
      if (scope.level === 'floor' && z.floorId !== scope.floorId) return false;
      if (memberZoneLimit && !memberZoneLimit.includes(z.id)) return false;
      return true;
    });
  }

  function getBuildingFloors(buildingId: string) {
    const list = tree.floors.filter((f) => {
      if (f.buildingId !== buildingId) return false;
      if (topology === 'floors-only') return session.scope.allowedFloorIds.includes(f.id);
      return true;
    });
    return [...list].sort((a, b) => parseFloorOrder(b.name) - parseFloorOrder(a.name));
  }

  async function setScope(next: HomeScope, preserveInitialQuery = false): Promise<void> {
    // 严格遵守拓扑边界：单层/租户模式不允许上钻到未授权层级
    let normalized = next;
    if (normalized.level === 'all-projects' && !canViewAllProjects) {
      normalized = { level: 'project', projectId: tree.projects[0]?.id ?? E7F_IDS.projectId };
    }
    if (normalized.level === 'project' && !canViewProject) {
      normalized = {
        level: 'building',
        projectId: normalized.projectId,
        buildingId: tree.buildings[0]?.id ?? E7F_IDS.buildingId,
      };
    }
    if (normalized.level === 'building' && !canViewBuilding) {
      normalized = {
        level: 'floor',
        projectId: normalized.projectId,
        buildingId: normalized.buildingId,
        floorId: allowedFloors[0]?.id ?? E7F_IDS.floorId,
      };
    }

    scope = normalized;
    setGlobalSpaceScope(normalized);
    floorError = null;
    zoneFilter = preserveInitialQuery && initZoneId ? initZoneId : 'all';
    briefingOpen = false;
    spacePopOpen = false;
    hudOpen = false;
    checkedDeviceIds.clear();
    zoom = 1;
    panX = 0;
    panY = 0;
    if (unsubscribe) {
      unsubscribe();
      unsubscribe = null;
    }

    const targetFloorId = scope.level === 'floor' ? scope.floorId : E7F_IDS.floorId;
    if (scope.level === 'floor') {
      try {
        const [devList, alarmList, woList] = await Promise.all([
          adapter.getFloorDevices(scope.floorId),
          adapter.listAlarms(scope.floorId),
          adapter.listWorkOrders(scope.floorId),
        ]);
        devices = devList;
        alarms = alarmList;
        workOrders = woList;
        if (!devices.some((d) => d.id === selectedDeviceId)) {
          selectedDeviceId = devices[1]?.id ?? devices[0]?.id ?? null;
          drawerOpen = false;
        } else if (preserveInitialQuery && initDeviceId) {
          drawerOpen = true;
        }
        unsubscribe = adapter.subscribeFloorEvents(scope.floorId, async (event) => {
          if (event.type === 'control.receipt.updated' && activeBatch?.batchId === event.batchId) {
            activeBatch = await adapter.getControlBatch(event.batchId);
          }
          if (event.type === 'telemetry.updated' || event.type === 'device.connectivity') {
            if (scope.level === 'floor') devices = await adapter.getFloorDevices(scope.floorId);
          }
          if (event.type === 'alarm.changed') {
            if (scope.level === 'floor') alarms = await adapter.listAlarms(scope.floorId);
          }
          renderPreservingFocus();
        });
      } catch (err) {
        devices = [];
        alarms = [];
        workOrders = [];
        selectedDeviceId = null;
        drawerOpen = false;
        floorError = err instanceof Error ? err.message : String(err);
      }
    } else {
      drawerOpen = false;
      const [devList, alarmList, woList] = await Promise.all([
        adapter.getFloorDevices(targetFloorId).catch(() => []),
        adapter.listAlarms(targetFloorId).catch(() => []),
        adapter.listWorkOrders(targetFloorId).catch(() => []),
      ]);
      devices = devList;
      alarms = alarmList;
      workOrders = woList;
    }
    render();
  }

  function getZoneName(zoneId?: string | null): string {
    if (!zoneId) return '未分配逻辑区';
    return tree.zones.find((z) => z.id === zoneId)?.name ?? zoneId;
  }

  function getFilteredDevices(): DeviceEntity[] {
    const q = searchKeyword.trim().toLowerCase();
    return devices.filter((d) => {
      if (zoneFilter !== 'all' && d.logicalZoneId !== zoneFilter) return false;
      if (categoryFilter !== 'all' && d.category !== categoryFilter) return false;
      if (!q) return true;
      return (
        d.name.toLowerCase().includes(q) ||
        d.id.toLowerCase().includes(q) ||
        getZoneName(d.logicalZoneId).toLowerCase().includes(q)
      );
    });
  }

  async function dispatchCommand(deviceIds: string[], command: ControlCommandType, targetValue: number | boolean | string): Promise<void> {
    if (!deviceIds.length || scope.level !== 'floor' || !canControl) return;
    deviceIds.forEach((id) => overriddenDeviceIds.add(id));
    activeBatch = await adapter.dispatchControlBatch({
      floorId: scope.floorId,
      idempotencyKey: `idem-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      targets: deviceIds.map((deviceId) => ({ deviceId, command, targetValue })),
    });
    renderPreservingFocus();
  }

  function renderPreservingFocus(): void {
    const active = document.activeElement as HTMLInputElement | null;
    const activeRole = active?.dataset?.role;
    const selStart = active && 'selectionStart' in active ? active.selectionStart : null;
    const selEnd = active && 'selectionEnd' in active ? active.selectionEnd : null;
    const listScrollTop = root.querySelector<HTMLElement>('.pacom-list')?.scrollTop ?? 0;

    render();

    const nextList = root.querySelector<HTMLElement>('.pacom-list');
    if (nextList) nextList.scrollTop = listScrollTop;
    if (activeRole === 'search' || activeRole === 'space-search') {
      const el = root.querySelector<HTMLInputElement>(`[data-role="${activeRole}"]`);
      if (el) {
        el.focus();
        if (selStart !== null && selEnd !== null) el.setSelectionRange(selStart, selEnd);
      }
    }
  }

  function applyViewportTransform(): void {
    const vp = root.querySelector<HTMLElement>('[data-role="canvas-viewport"]');
    if (vp) vp.style.transform = `translate(${panX}px, ${panY}px) scale(${zoom})`;
    const zoomLbl = root.querySelector<HTMLElement>('[data-role="zoom-label"]');
    if (zoomLbl) zoomLbl.textContent = `${Math.round(zoom * 100)}%`;
  }

  function parseScopeValue(raw: string): HomeScope {
    if (raw === 'all') return { level: 'all-projects' };
    const parts = raw.split(':');
    if (parts[0] === 'project' && parts[1]) return { level: 'project', projectId: parts[1] };
    if (parts[0] === 'building' && parts[1] && parts[2]) return { level: 'building', projectId: parts[1], buildingId: parts[2] };
    if (parts[0] === 'floor' && parts[1] && parts[2] && parts[3]) return { level: 'floor', projectId: parts[1], buildingId: parts[2], floorId: parts[3] };
    return { level: 'all-projects' };
  }

  function renderSpaceTrigger(): string {
    const s = scope;
    const curProj =
      s.level === 'all-projects'
        ? null
        : tree.projects.find((p) => p.id === s.projectId) ?? tree.projects[0];
    const curBld =
      s.level === 'building' || s.level === 'floor'
        ? tree.buildings.find((b) => b.id === s.buildingId)
        : null;
    const curFloor =
      s.level === 'floor' ? tree.floors.find((f) => f.id === s.floorId) : null;

    const parts: string[] = [];
    if (scope.level === 'all-projects') {
      parts.push(`全部项目（${tree.projects.length}）`);
    } else if (scope.level === 'project') {
      parts.push(escapeHtml(curProj?.name ?? '园区'));
    } else if (scope.level === 'building') {
      if (canViewProject && curProj) parts.push(`<span class="pacom-space-trigger-muted">${escapeHtml(curProj.name)}</span>`);
      parts.push(escapeHtml(curBld?.name ?? '楼宇'));
    } else {
      if (canViewProject && curProj) parts.push(`<span class="pacom-space-trigger-muted">${escapeHtml(curProj.name)}</span>`);
      if (canViewBuilding && curBld) parts.push(`<span class="pacom-space-trigger-muted">${escapeHtml(curBld.name)}</span>`);
      const floorText = !canViewBuilding && curBld ? `${curBld.name} ${curFloor?.name ?? '7F'}` : (curFloor?.name ?? '7F');
      parts.push(escapeHtml(floorText));
    }

    const sep = `<span class="pacom-space-trigger-muted" style="margin:0 2px;">·</span>`;
    if (isSingleFloorOnly) {
      return `<span class="pacom-hud-space-btn is-static" title="当前授权空间">${parts.join(sep)}</span>`;
    }

    return `
      <button type="button" class="pacom-hud-space-btn" data-toggle-space-pop="1" aria-expanded="${spacePopOpen}" aria-haspopup="dialog" title="切换项目 / 楼宇 / 楼层">
        <span>${parts.join(sep)}</span>
        <span style="display:inline-flex; color:var(--pacom-text-secondary);">${CHEVRON_DOWN_SVG}</span>
      </button>
    `;
  }

  function renderSpacePopover(activeAlarmCount: number): string {
    if (!spacePopOpen || isSingleFloorOnly) return '';
    const q = spaceSearch.trim().toLowerCase();
    const activeProjectId = scope.level === 'all-projects' ? (tree.projects[0]?.id ?? E7F_IDS.projectId) : scope.projectId;
    const activeBuildingId =
      scope.level === 'building' || scope.level === 'floor'
        ? scope.buildingId
        : (tree.buildings.find((b) => b.projectId === activeProjectId)?.id ?? E7F_IDS.buildingId);

    const matchedProjects = tree.projects.filter((p) => !q || p.name.toLowerCase().includes(q));
    const matchedBuildings = tree.buildings.filter(
      (b) => b.projectId === activeProjectId && (!q || b.name.toLowerCase().includes(q))
    );
    const matchedFloors = getBuildingFloors(activeBuildingId).filter(
      (f) => !q || f.name.toLowerCase().includes(q)
    );

    const showProjectCol = canViewAllProjects;
    const showBuildingCol = canViewProject;

    return `
      <div class="pacom-space-popover" role="dialog" aria-label="空间快速切换" data-role="space-popover">
        <div class="pacom-space-pop-head">
          ${renderIcon('search', 14)}
          <input type="text" name="spaceQuickSearch" data-role="space-search" placeholder="快速检索园区、楼宇或楼层…" value="${escapeHtml(spaceSearch)}" aria-label="检索空间" />
          <button type="button" class="pacom-drawer-close" style="width:24px; height:24px;" data-toggle-space-pop="1" aria-label="关闭">${renderIcon('x', 14)}</button>
        </div>
        <div class="pacom-space-pop-cols">
          ${
            showProjectCol
              ? `
              <div class="pacom-space-pop-col">
                <div class="pacom-space-pop-label">园区 / 项目</div>
                ${
                  canViewAllProjects
                    ? `<button type="button" class="pacom-space-pop-item ${scope.level === 'all-projects' ? 'is-active' : ''}" data-nav-scope="all">
                        <span>全部项目（${tree.projects.length}）</span>
                        ${scope.level === 'all-projects' ? renderIcon('check', 14) : ''}
                      </button>`
                    : ''
                }
                ${matchedProjects
                  .map((p) => {
                    const isAct = scope.level === 'project' && scope.projectId === p.id;
                    return `<button type="button" class="pacom-space-pop-item ${isAct ? 'is-active' : ''}" data-nav-scope="project:${escapeHtml(p.id)}">
                      <span>${escapeHtml(p.name)}</span>
                      ${isAct ? renderIcon('check', 14) : renderIcon('chevron-right', 12)}
                    </button>`;
                  })
                  .join('')}
              </div>`
              : ''
          }
          ${
            showBuildingCol
              ? `
              <div class="pacom-space-pop-col">
                <div class="pacom-space-pop-label">${escapeHtml(tree.projects.find((p) => p.id === activeProjectId)?.name ?? '园区')} · 楼宇</div>
                ${
                  canViewProject
                    ? `<button type="button" class="pacom-space-pop-item ${scope.level === 'project' ? 'is-active' : ''}" data-nav-scope="project:${escapeHtml(activeProjectId)}">
                        <span>园区总览</span>
                        ${scope.level === 'project' ? renderIcon('check', 14) : ''}
                      </button>`
                    : ''
                }
                ${matchedBuildings
                  .map((b) => {
                    const isAct = scope.level === 'building' && scope.buildingId === b.id;
                    const isPilot = b.id === E7F_IDS.buildingId;
                    return `<button type="button" class="pacom-space-pop-item ${isAct ? 'is-active' : ''}" data-nav-scope="building:${escapeHtml(b.projectId)}:${escapeHtml(b.id)}">
                      <span style="display:inline-flex; align-items:center; gap:6px;">
                        <span>${escapeHtml(b.name)}</span>
                        ${isPilot && activeAlarmCount > 0 ? '<span class="pacom-elev-dot" title="有活跃告警"></span>' : ''}
                      </span>
                      ${isAct ? renderIcon('check', 14) : renderIcon('chevron-right', 12)}
                    </button>`;
                  })
                  .join('')}
              </div>`
              : ''
          }
          <div class="pacom-space-pop-col">
            <div class="pacom-space-pop-label">${escapeHtml(tree.buildings.find((b) => b.id === activeBuildingId)?.name ?? '楼宇')} · 楼层</div>
            ${
              canViewBuilding
                ? `<button type="button" class="pacom-space-pop-item ${scope.level === 'building' && scope.buildingId === activeBuildingId ? 'is-active' : ''}" data-nav-scope="building:${escapeHtml(activeProjectId)}:${escapeHtml(activeBuildingId)}">
                    <span>整栋视图</span>
                    ${scope.level === 'building' && scope.buildingId === activeBuildingId ? renderIcon('check', 14) : ''}
                  </button>`
                : ''
            }
            ${matchedFloors
              .map((f) => {
                const allowed = session.scope.allowedFloorIds.includes(f.id);
                const isAct = scope.level === 'floor' && scope.floorId === f.id;
                const hasAlarm = f.id === E7F_IDS.floorId && activeAlarmCount > 0;
                return `<button type="button" class="pacom-space-pop-item ${isAct ? 'is-active' : ''}" style="${allowed ? '' : 'opacity:0.5;'}" data-nav-scope="floor:${escapeHtml(activeProjectId)}:${escapeHtml(activeBuildingId)}:${escapeHtml(f.id)}">
                  <span style="display:inline-flex; align-items:center; gap:6px;">
                    <span>${escapeHtml(f.name)}</span>
                    ${hasAlarm ? `<span class="pacom-elev-dot"></span>` : ''}
                  </span>
                  <span class="pacom-row-sub" style="font-size:11px;">${isAct ? renderIcon('check', 14) : allowed ? (f.plan ? '2D' : '待部署') : '未授权'}</span>
                </button>`;
              })
              .join('')}
          </div>
        </div>
      </div>
    `;
  }

  function renderHudSheetBody(activeAlarmCount: number): string {
    const s = scope;
    if (s.level === 'all-projects') {
      const q = searchKeyword.trim().toLowerCase();
      const list = tree.projects.filter((p) => !q || p.name.toLowerCase().includes(q));
      return `
        <div class="pacom-hud-sheet-head">
          <strong style="font-size:13px; font-weight:500;">授权园区（${list.length}）</strong>
          <button type="button" class="pacom-drawer-close" data-close-hud="1" aria-label="收起列表">${renderIcon('x', 14)}</button>
        </div>
        <div class="pacom-list" style="gap:6px; padding:8px;">
          ${list
            .map((p) => {
              const bCount = tree.buildings.filter((b) => b.projectId === p.id).length;
              return `
                <button type="button" class="pacom-row" style="width:100%; background:transparent; text-align:left;" data-nav-scope="project:${escapeHtml(p.id)}">
                  <div>
                    <div class="pacom-row-title">${escapeHtml(p.name)}</div>
                    <div class="pacom-row-sub">${escapeHtml(p.city ?? '')} · ${bCount} 栋楼宇</div>
                  </div>
                  <span class="pacom-badge pacom-badge--accent">进入 →</span>
                </button>`;
            })
            .join('')}
        </div>
      `;
    }

    if (s.level === 'project') {
      const q = searchKeyword.trim().toLowerCase();
      const blds = tree.buildings.filter((b) => b.projectId === s.projectId && (!q || b.name.toLowerCase().includes(q)));
      const onlineCount = devices.filter((d) => d.connectivity === 'online').length;
      const onlineRate = devices.length ? Math.round((onlineCount / devices.length) * 100) : 100;
      return `
        <div class="pacom-hud-sheet-head">
          <strong style="font-size:13px; font-weight:500;">园区楼宇（${blds.length}）</strong>
          <button type="button" class="pacom-drawer-close" data-close-hud="1" aria-label="收起列表">${renderIcon('x', 14)}</button>
        </div>
        <div class="pacom-list" style="gap:4px; padding:8px;">
          ${blds
            .map((b) => {
              const isPilot = b.id === E7F_IDS.buildingId;
              return `
                <button type="button" class="pacom-row" style="width:100%; background:transparent; text-align:left;" data-nav-scope="building:${escapeHtml(b.projectId)}:${escapeHtml(b.id)}">
                  <div style="display:flex; align-items:center; gap:8px; min-width:0;">
                    <span class="pacom-dot ${isPilot && activeAlarmCount > 0 ? 'pacom-dot--warning' : 'pacom-dot--online'}"></span>
                    <div>
                      <div class="pacom-row-title">${escapeHtml(b.name)}</div>
                      <div class="pacom-row-sub">地上 ${b.aboveFloors} 层 · ${b.areaSqm ?? '-'} m²</div>
                    </div>
                  </div>
                  <span class="pacom-badge ${isPilot ? 'pacom-badge--accent' : 'pacom-badge--neutral'}">${isPilot ? `在线 ${onlineRate}%` : '运行平稳'}</span>
                </button>`;
            })
            .join('')}
        </div>
      `;
    }

    if (s.level === 'building') {
      const q = searchKeyword.trim().toLowerCase();
      const floors = getBuildingFloors(s.buildingId).filter((f) => !q || f.name.toLowerCase().includes(q));
      const bld = tree.buildings.find((b) => b.id === s.buildingId);
      return `
        <div class="pacom-hud-sheet-head">
          <strong style="font-size:13px; font-weight:500;">${escapeHtml(bld?.name ?? '楼宇')} 楼层导览（${floors.length}）</strong>
          <button type="button" class="pacom-drawer-close" data-close-hud="1" aria-label="收起列表">${renderIcon('x', 14)}</button>
        </div>
        <div class="pacom-list" style="gap:4px; padding:8px;">
          ${floors
            .map((f) => {
              const allowed = session.scope.allowedFloorIds.includes(f.id);
              const isE7F = f.id === E7F_IDS.floorId;
              return `
                <button type="button" class="pacom-row" style="width:100%; background:transparent; text-align:left; ${allowed ? '' : 'opacity:0.6;'}" data-nav-scope="floor:${escapeHtml(s.projectId)}:${escapeHtml(s.buildingId)}:${escapeHtml(f.id)}">
                  <div style="display:flex; align-items:center; gap:8px;">
                    <span class="pacom-dot ${isE7F && activeAlarmCount > 0 ? 'pacom-dot--warning' : f.plan ? 'pacom-dot--online' : 'pacom-dot--offline'}"></span>
                    <div>
                      <div class="pacom-row-title">${escapeHtml(bld?.name ?? '')} ${escapeHtml(f.name)}</div>
                      <div class="pacom-row-sub">${f.plan ? '2D 平面控图就绪' : '暂未上传平面图'}${isE7F && activeAlarmCount > 0 ? ` · ${activeAlarmCount} 告警` : ''}</div>
                    </div>
                  </div>
                  <span class="pacom-badge ${allowed && f.plan ? 'pacom-badge--online' : 'pacom-badge--neutral'}">${allowed ? (f.plan ? '进入 →' : '待部署') : '未授权'}</span>
                </button>`;
            })
            .join('')}
        </div>
      `;
    }

    // Floor level HUD sheet: Devices / Zones / Alarms
    if (activeTab === 'devices') {
      const list = getFilteredDevices();
      const zones = visibleZones();
      const batchableIds = Array.from(checkedDeviceIds);
      return `
        <div class="pacom-pane-toolbar" style="padding:10px 12px; gap:8px;">
          ${
            memberZoneLimit
              ? `<div class="pacom-info-banner">我的区域视图：仅显示获授权的 ${memberZoneLimit.length} 个功能区及设备。</div>`
              : ''
          }
          <div style="display:flex; align-items:center; justify-content:space-between; gap:8px;">
            <select class="pacom-select" style="height:28px; font-size:12px;" name="deviceCategory" data-role="category" aria-label="按设备类型筛选">
              <option value="all" ${categoryFilter === 'all' ? 'selected' : ''}>全部类型</option>
              <option value="lighting" ${categoryFilter === 'lighting' ? 'selected' : ''}>照明</option>
              <option value="hvac" ${categoryFilter === 'hvac' ? 'selected' : ''}>暖通空调</option>
              <option value="sensor" ${categoryFilter === 'sensor' ? 'selected' : ''}>环境传感</option>
              <option value="gateway" ${categoryFilter === 'gateway' ? 'selected' : ''}>网关</option>
            </select>
            <span style="font-size:12px; color:var(--pacom-text-secondary);">可见 ${list.length} 台${canControl && batchableIds.length ? ` · 已选 ${batchableIds.length}` : ''}</span>
            <button type="button" class="pacom-drawer-close" data-close-hud="1" aria-label="收起列表">${renderIcon('x', 14)}</button>
          </div>
          ${
            zones.length > 0 && !floorError
              ? `<div class="pacom-zone-pills" role="group" aria-label="按功能区筛选">
                  <button type="button" class="pacom-zone-pill ${zoneFilter === 'all' ? 'is-active' : ''}" data-filter-zone="all">全部区域</button>
                  ${zones
                    .map(
                      (z) =>
                        `<button type="button" class="pacom-zone-pill ${zoneFilter === z.id ? 'is-active' : ''}" data-filter-zone="${escapeHtml(z.id)}">${escapeHtml(z.name.replace(/^7F\s*/, ''))}</button>`
                    )
                    .join('')}
                </div>`
              : ''
          }
        </div>
        <div class="pacom-list" style="padding:6px;">
          ${
            floorError
              ? `<div class="pacom-alert-banner">${escapeHtml(floorError)}</div>`
              : list.length === 0
                ? `<div class="pacom-row-sub" style="padding:20px; text-align:center;">没有匹配的设备</div>`
                : list
                    .map((d) => {
                      const isSelected = d.id === selectedDeviceId && drawerOpen;
                      const isChecked = checkedDeviceIds.has(d.id);
                      const isOffline = d.connectivity === 'offline';
                      const dotClass = isOffline ? 'pacom-dot--critical' : 'pacom-dot--online';
                      const summary = isOffline
                        ? '离线'
                        : d.category === 'lighting'
                          ? `${d.telemetry.dimming?.value ?? '--'}%`
                          : d.category === 'hvac'
                            ? `${d.telemetry.setpoint?.value ?? '--'}°C`
                            : d.category === 'sensor'
                              ? `${d.telemetry.temp?.value ?? '--'}°C`
                              : '在线';
                      return `
                        <div class="pacom-row ${isSelected ? 'is-selected' : ''}" data-select-device="${escapeHtml(d.id)}" style="padding:8px;">
                          <div class="pacom-row-main">
                            ${
                              canControl
                                ? `<input type="checkbox" name="devCheck-${escapeHtml(d.id)}" data-check-device="${escapeHtml(d.id)}" ${isChecked ? 'checked' : ''} style="margin-top:3px;" aria-label="勾选 ${escapeHtml(d.name)}" />`
                                : ''
                            }
                            <div style="min-width:0;">
                              <div class="pacom-row-title" style="font-size:13px;">${escapeHtml(d.name)}</div>
                              <div class="pacom-row-sub">${escapeHtml(getZoneName(d.logicalZoneId).replace(/^7F\s*/, ''))} · ${escapeHtml(CATEGORY_LABELS[d.category])}</div>
                            </div>
                          </div>
                          <span class="pacom-badge ${isOffline ? 'pacom-badge--critical' : 'pacom-badge--online'}">
                            <span class="pacom-dot ${dotClass}"></span>${escapeHtml(summary)}
                          </span>
                        </div>`;
                    })
                    .join('')
          }
        </div>
        ${
          canControl && batchableIds.length > 0
            ? `
            <div class="pacom-batch-bar" style="padding:8px 12px;">
              <span style="font-size:12px;">已选 <strong>${batchableIds.length} 台</strong></span>
              <div style="display:flex; gap:6px;">
                <button type="button" class="pacom-btn" style="height:28px; font-size:12px;" data-batch-cmd="lighting.power" data-batch-val="true">批量开启</button>
                <button type="button" class="pacom-btn pacom-btn--primary" style="height:28px; font-size:12px;" data-batch-cmd="lighting.power" data-batch-val="false">批量关闭</button>
              </div>
            </div>`
            : ''
        }
      `;
    }

    if (activeTab === 'zones') {
      const zones = visibleZones();
      const zoneTelemetry: Record<string, { temp: string; occ: string }> = {
        'zone-e7f-lab-east': { temp: '23.2°C', occ: '有人 74%' },
        'zone-e7f-office-west': { temp: '24.1°C', occ: '有人 52%' },
        'zone-e7f-meeting-702': { temp: '22.8°C', occ: '会议中' },
        'zone-e7f-corridor': { temp: '23.9°C', occ: '通行区' },
      };
      return `
        <div class="pacom-hud-sheet-head">
          <strong style="font-size:13px; font-weight:500;">功能区快控（${zones.length}）</strong>
          <button type="button" class="pacom-drawer-close" data-close-hud="1" aria-label="收起列表">${renderIcon('x', 14)}</button>
        </div>
        <div class="pacom-list" style="gap:8px; padding:10px;">
          ${zones
            .map((z) => {
              const zDevices = devices.filter((d) => d.logicalZoneId === z.id);
              const onlineCnt = zDevices.filter((d) => d.connectivity === 'online').length;
              const controllableCnt = zDevices.filter((d) => d.category === 'lighting' || d.category === 'hvac').length;
              const isActive = zoneFilter === z.id;
              const meta = zoneTelemetry[z.id] ?? { temp: '23.4°C', occ: '正常' };
              return `
                <div class="pacom-control-box" style="background:${isActive ? 'var(--pacom-surface-card)' : '#fff'}; cursor:pointer; ${isActive ? 'box-shadow:0 0 0 1.5px var(--pacom-accent-solid);' : ''}" data-filter-zone="${escapeHtml(isActive ? 'all' : z.id)}">
                  <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                    <strong style="font-size:13px; font-weight:500;">${escapeHtml(z.name.replace(/^7F\s*/, ''))}</strong>
                    <span class="pacom-badge pacom-badge--online">在线 ${onlineCnt}/${zDevices.length}</span>
                  </div>
                  <div class="pacom-row-sub">实时 ${meta.temp} · ${meta.occ}</div>
                  ${
                    controllableCnt > 0
                      ? `
                      <div style="display:flex; gap:6px;">
                        <button type="button" class="pacom-btn" style="height:28px; font-size:12px;" data-zone-power="${escapeHtml(z.id)}" data-zone-val="true" ${canControl ? '' : 'disabled'}>区域全开</button>
                        <button type="button" class="pacom-btn pacom-btn--primary" style="height:28px; font-size:12px;" data-zone-power="${escapeHtml(z.id)}" data-zone-val="false" ${canControl ? '' : 'disabled'}>区域全关</button>
                      </div>`
                      : `<div class="pacom-row-sub">弱电 / 网关基础区</div>`
                  }
                </div>`;
            })
            .join('')}
        </div>
      `;
    }

    return `
      <div class="pacom-hud-sheet-head">
        <strong style="font-size:13px; font-weight:500;">本层告警（${alarms.length}）</strong>
        <div style="display:flex; align-items:center; gap:4px;">
          <button type="button" class="pacom-btn pacom-btn--ghost" style="height:24px; padding:0 8px; font-size:12px;" data-go-alarms="1">告警中心 →</button>
          <button type="button" class="pacom-drawer-close" data-close-hud="1" aria-label="收起列表">${renderIcon('x', 14)}</button>
        </div>
      </div>
      <div class="pacom-list" style="gap:8px; padding:10px;">
        ${
          alarms.length === 0
            ? `<div class="pacom-row-sub" style="padding:20px; text-align:center;">当前楼层无活跃告警</div>`
            : alarms
                .map(
                  (a) => `
                  <div class="pacom-control-box" style="background:#fff;">
                    <div style="display:flex; justify-content:space-between; align-items:center; gap:6px;">
                      <strong style="font-size:13px;">${escapeHtml(a.title)}</strong>
                      <span class="pacom-badge ${a.status === 'active' ? 'pacom-badge--warning' : 'pacom-badge--online'}">${a.status === 'active' ? '待处理' : '已确认'}</span>
                    </div>
                    <div class="pacom-row-sub">${escapeHtml(a.message)}</div>
                    <div style="display:flex; gap:6px; flex-wrap:wrap;">
                      <button type="button" class="pacom-btn" style="height:28px; font-size:12px;" data-locate-device="${escapeHtml(a.deviceId)}">定位设备</button>
                      ${
                        a.status === 'active'
                          ? `<button type="button" class="pacom-btn pacom-btn--primary" style="height:28px; font-size:12px;" data-ack-alarm="${escapeHtml(a.id)}" ${canManageAlarms ? '' : 'disabled title="当前角色无告警处理权限"'}>快速确认</button>`
                          : ''
                      }
                    </div>
                  </div>`
                )
                .join('')
        }
      </div>
    `;
  }

  function renderFloatingHud(activeAlarmCount: number): string {
    const s = scope;
    const zonesCount = visibleZones().length;
    const placeholder =
      s.level === 'floor'
        ? '搜索设备或区域…'
        : s.level === 'building'
          ? '搜索楼层…'
          : s.level === 'project'
            ? '搜索楼宇…'
            : '搜索园区…';

    const pills =
      s.level === 'floor'
        ? `
          <button type="button" class="pacom-hud-pill ${hudOpen && activeTab === 'devices' ? 'is-active' : ''}" data-hud-tab="devices">设备 ${devices.length}</button>
          <button type="button" class="pacom-hud-pill ${hudOpen && activeTab === 'zones' ? 'is-active' : ''}" data-hud-tab="zones">区域 ${zonesCount}</button>
          <button type="button" class="pacom-hud-pill ${activeAlarmCount > 0 ? 'pacom-hud-pill--alert' : ''} ${hudOpen && activeTab === 'alarms' ? 'is-active' : ''}" data-hud-tab="alarms">告警 ${activeAlarmCount}</button>
        `
        : s.level === 'building'
          ? `
            <button type="button" class="pacom-hud-pill ${hudOpen ? 'is-active' : ''}" data-toggle-hud="1">楼层 ${getBuildingFloors(s.buildingId).length}</button>
            ${activeAlarmCount > 0 ? `<button type="button" class="pacom-hud-pill pacom-hud-pill--alert" data-go-alarms="1">告警 ${activeAlarmCount}</button>` : ''}
          `
          : s.level === 'project'
            ? `
              <button type="button" class="pacom-hud-pill ${hudOpen ? 'is-active' : ''}" data-toggle-hud="1">楼宇 ${tree.buildings.filter((b) => b.projectId === s.projectId).length}</button>
              ${activeAlarmCount > 0 ? `<button type="button" class="pacom-hud-pill pacom-hud-pill--alert" data-go-alarms="1">告警 ${activeAlarmCount}</button>` : ''}
            `
            : `<button type="button" class="pacom-hud-pill ${hudOpen ? 'is-active' : ''}" data-toggle-hud="1">园区 ${tree.projects.length}</button>`;

    return `
      <div class="pacom-hud-search-wrap" data-role="hud-wrap">
        <div class="pacom-hud-bar" style="padding:0 8px 0 12px;">
          ${renderIcon('search', 14)}
          <input class="pacom-hud-input" name="spatialSearch" data-role="search" placeholder="${placeholder}" value="${escapeHtml(searchKeyword)}" aria-label="${placeholder}" />
          ${pills}
        </div>
        ${hudOpen ? `<div class="pacom-hud-sheet" data-role="hud-sheet">${renderHudSheetBody(activeAlarmCount)}</div>` : ''}
      </div>
    `;
  }

  function renderElevationScrubber(activeAlarmCount: number): string {
    if (isSingleFloorOnly) return '';
    if (scope.level !== 'building' && scope.level !== 'floor') return '';
    const buildingId = scope.buildingId;
    const projectId = scope.projectId;
    const floors = getBuildingFloors(buildingId);
    if (!canViewBuilding && floors.length <= 1) return '';

    return `
      <nav class="pacom-elevation-scrubber" aria-label="建筑标高楼层切换" data-role="elevation-scrubber">
        ${
          canViewBuilding
            ? `<button type="button" class="pacom-elev-item ${scope.level === 'building' ? 'is-active' : ''}" data-nav-scope="building:${escapeHtml(projectId)}:${escapeHtml(buildingId)}" title="查看整栋视图">
                <span>栋</span>
                <span class="pacom-elev-tick"></span>
              </button>`
            : ''
        }
        ${floors
          .map((f) => {
            const allowed = session.scope.allowedFloorIds.includes(f.id);
            const isActive = scope.level === 'floor' && scope.floorId === f.id;
            const hasAlarm = f.id === E7F_IDS.floorId && activeAlarmCount > 0;
            return `
              <button type="button" class="pacom-elev-item ${isActive ? 'is-active' : ''} ${allowed ? '' : 'is-locked'}"
                data-nav-scope="floor:${escapeHtml(projectId)}:${escapeHtml(buildingId)}:${escapeHtml(f.id)}"
                title="${escapeHtml(f.name)}${allowed ? (hasAlarm ? ` · ${activeAlarmCount} 条告警` : '') : '（无权限）'}">
                ${hasAlarm ? '<span class="pacom-elev-dot" aria-hidden="true"></span>' : ''}
                <span>${escapeHtml(f.name)}</span>
                <span class="pacom-elev-tick"></span>
              </button>`;
          })
          .join('')}
      </nav>
    `;
  }

  function renderBottomDock(onlineCount: number, activeAlarmCount: number): string {
    const s = scope;
    if (s.level === 'floor') {
      if (floorError) return '';
      return `
        <div class="pacom-canvas-dock" role="toolbar" aria-label="平面图图层与缩放控制">
          <button type="button" class="pacom-dock-btn" aria-pressed="${canvasLayer === 'devices'}" data-canvas-layer="devices">设备点位</button>
          <button type="button" class="pacom-dock-btn" aria-pressed="${canvasLayer === 'temp'}" data-canvas-layer="temp">温度热力</button>
          <button type="button" class="pacom-dock-btn" aria-pressed="${canvasLayer === 'occupancy'}" data-canvas-layer="occupancy">占用状态</button>
          <span class="pacom-dock-sep" aria-hidden="true"></span>
          <button type="button" class="pacom-dock-icon" data-zoom="out" title="缩小" aria-label="缩小">${renderIcon('minus', 14)}</button>
          <button type="button" class="pacom-dock-btn" style="padding:0 8px; font-variant-numeric:tabular-nums;" data-zoom="reset" data-role="zoom-label" title="点击复位 100%">${Math.round(zoom * 100)}%</button>
          <button type="button" class="pacom-dock-icon" data-zoom="in" title="放大" aria-label="放大">${renderIcon('plus', 14)}</button>
        </div>
      `;
    }

    const onlineRate = devices.length ? Math.round((onlineCount / devices.length) * 100) : 100;
    const energyText = s.level === 'building' ? '418 kWh' : '1,248 kWh';
    const healthScore = Math.round(96.2 * 0.45 + 93.6 * 0.35 + onlineRate * 0.2);
    const defaultFloor = s.level === 'building'
      ? (getBuildingFloors(s.buildingId).find((f) => f.id === E7F_IDS.floorId) ?? getBuildingFloors(s.buildingId)[0])
      : null;

    return `
      <div class="pacom-canvas-dock" role="region" aria-label="空间运行态势">
        <button type="button" class="pacom-dock-metric" data-go-analysis="health">
          <span class="pacom-dot pacom-dot--online"></span>
          <span>健康 <strong>${healthScore}</strong></span>
        </button>
        <span class="pacom-dock-sep" aria-hidden="true"></span>
        <button type="button" class="pacom-dock-metric" data-go-analysis="environment">
          <span>舒适度 <strong>96.2%</strong></span>
        </button>
        <span class="pacom-dock-sep" aria-hidden="true"></span>
        <button type="button" class="pacom-dock-metric" data-go-analysis="energy">
          <span>今日能耗 <strong>${energyText}</strong></span>
        </button>
        <span class="pacom-dock-sep" aria-hidden="true"></span>
        <button type="button" class="pacom-dock-metric" data-go-alarms="1">
          <span class="pacom-dot ${activeAlarmCount > 0 ? 'pacom-dot--warning' : 'pacom-dot--online'}"></span>
          <span>告警 <strong>${activeAlarmCount}</strong></span>
        </button>
        ${
          s.level === 'building' && defaultFloor
            ? `<span class="pacom-dock-sep" aria-hidden="true"></span>
               <button type="button" class="pacom-dock-btn" aria-pressed="true" data-nav-scope="floor:${escapeHtml(s.projectId)}:${escapeHtml(s.buildingId)}:${escapeHtml(defaultFloor.id)}">进入 ${escapeHtml(defaultFloor.name)} 平面图 →</button>`
            : ''
        }
      </div>
    `;
  }

  function renderSpatialCanvas(onlineCount: number, activeAlarmCount: number): string {
    const s = scope;
    const onlineRate = devices.length ? Math.round((onlineCount / devices.length) * 100) : 100;

    if (s.level === 'all-projects') {
      return `
        <div class="pacom-canvas-stage" style="display:flex; align-items:center; justify-content:center; padding:48px 24px 72px; cursor:default; background:radial-gradient(circle at 50% 45%, #fafaf9 0%, #f1f1ef 100%);">
          <div style="position:relative; width:min(920px, 94%); height:min(520px, 74vh); border-radius:16px; background:#ffffff; box-shadow:var(--pacom-shadow-sm); overflow:hidden;">
            <svg viewBox="0 0 920 520" style="width:100%; height:100%; display:block;" aria-label="多园区空间分布底图">
              <defs>
                <pattern id="pacom-map-grid" width="40" height="40" patternUnits="userSpaceOnUse">
                  <path d="M 40 0 L 0 0 0 40" fill="none" stroke="oklch(88% 0 107 / 0.55)" stroke-width="0.75" />
                </pattern>
              </defs>
              <rect width="920" height="520" fill="url(#pacom-map-grid)" />
              <path d="M 80 340 Q 260 280 460 300 T 840 210" fill="none" stroke="oklch(82% 0.02 220 / 0.55)" stroke-width="18" stroke-linecap="round" />
              <path d="M 180 90 L 340 440 M 540 60 L 660 460" fill="none" stroke="oklch(86% 0 107 / 0.7)" stroke-width="2" stroke-dasharray="6 6" />
            </svg>
            ${tree.projects
              .map(
                (p, idx) => `
                <button type="button" class="pacom-pin is-selected" style="left:${idx === 0 ? 50 : 28}%; top:${idx === 0 ? 52 : 34}%; padding:0 12px; height:32px; font-size:12px;" data-nav-scope="project:${escapeHtml(p.id)}">
                  <span class="pacom-dot ${activeAlarmCount > 0 ? 'pacom-dot--warning' : 'pacom-dot--online'}"></span>
                  <span>${escapeHtml(p.name)} · 在线 ${onlineRate}%</span>
                </button>`
              )
              .join('')}
          </div>
        </div>
      `;
    }

    if (s.level === 'project') {
      const focusProject = tree.projects.find((p) => p.id === s.projectId) ?? tree.projects[0];
      const blds = tree.buildings.filter((b) => !focusProject || b.projectId === focusProject.id);
      return `
        <div class="pacom-canvas-stage" style="display:flex; align-items:center; justify-content:center; padding:48px 24px 72px; cursor:default;">
          <div style="position:relative; width:min(940px, 92%); border-radius:16px; overflow:hidden; box-shadow:0 14px 36px rgba(15,23,42,0.12); background:#fff;">
            <img src="${escapeHtml(focusProject?.imageUrl ?? './media/gzlab.jpg')}" alt="${escapeHtml(focusProject?.name ?? '园区')}俯瞰" style="width:100%; max-height:72vh; object-fit:cover; display:block;" />
            ${blds
              .map((b, idx) => {
                const isPilot = b.id === E7F_IDS.buildingId;
                return `
                  <button type="button" class="pacom-pin ${isPilot ? 'is-selected' : ''}" style="left:${idx === 0 ? 56 : 38}%; top:${idx === 0 ? 44 : 62}%; height:30px; padding:0 11px;" data-nav-scope="building:${escapeHtml(b.projectId)}:${escapeHtml(b.id)}">
                    <span class="pacom-dot ${isPilot && activeAlarmCount > 0 ? 'pacom-dot--warning' : 'pacom-dot--online'}"></span>
                    <span>${escapeHtml(b.name)} · ${isPilot ? `在线 ${onlineRate}% · 告警 ${activeAlarmCount}` : '运行平稳'}</span>
                  </button>`;
              })
              .join('')}
          </div>
        </div>
      `;
    }

    if (s.level === 'building') {
      const bld = tree.buildings.find((b) => b.id === s.buildingId);
      const defaultFloor = getBuildingFloors(s.buildingId).find((f) => f.id === E7F_IDS.floorId) ?? getBuildingFloors(s.buildingId)[0];
      return `
        <div class="pacom-canvas-stage" style="display:flex; align-items:center; justify-content:center; padding:48px 68px 72px 24px; cursor:default;">
          <div style="position:relative; display:inline-block;">
            <img class="pacom-plan-img" src="${escapeHtml(bld?.imageUrl ?? './media/building-e.png')}" alt="${escapeHtml(bld?.name ?? '楼宇')} 整栋实景图" style="max-height:74vh;" />
            ${
              defaultFloor
                ? `<button type="button" class="pacom-pin is-selected" style="left:52%; top:38%; height:30px; padding:0 11px;" data-nav-scope="floor:${escapeHtml(s.projectId)}:${escapeHtml(s.buildingId)}:${escapeHtml(defaultFloor.id)}">
                    <span class="pacom-dot ${activeAlarmCount > 0 ? 'pacom-dot--warning' : 'pacom-dot--online'}"></span>
                    <span>${escapeHtml(bld?.name ?? '')} ${escapeHtml(defaultFloor.name)} · 在线 ${onlineCount}/${devices.length}</span>
                  </button>`
                : ''
            }
          </div>
        </div>
      `;
    }

    // Floor level 2D full-bleed canvas
    const activeFloor = tree.floors.find((f) => f.id === s.floorId);
    const zones = visibleZones();

    return `
      <div class="pacom-canvas-stage" data-role="canvas-stage">
        ${
          floorError
            ? `<div style="height:100%; display:flex; align-items:center; justify-content:center; padding:24px;">
                <div class="pacom-alert-banner">${escapeHtml(floorError)}（已严格保留当前楼层上下文，不静默跳转到其他楼层）</div>
              </div>`
            : `<div class="pacom-canvas-viewport" data-role="canvas-viewport" style="transform: translate(${panX}px, ${panY}px) scale(${zoom});">
                <div class="pacom-plan-wrap">
                  <img class="pacom-plan-img" src="${escapeHtml(activeFloor?.plan?.imageUrl ?? './media/7F.webp')}" alt="E栋 ${escapeHtml(activeFloor?.name ?? '7F')} 平面图" />
                  ${zones
                    .map((z, idx) => {
                      const box = E7F_ZONE_BOXES[z.id];
                      if (!box) return '';
                      const isActive = zoneFilter === z.id;
                      const tempVals = ['23.2°C', '24.6°C', '22.8°C', '23.9°C'];
                      const occVals = ['有人 74%', '会议中', '有人 52%', '空闲'];
                      const layerSuffix = canvasLayer === 'temp' ? ` · ${tempVals[idx % tempVals.length]}` : canvasLayer === 'occupancy' ? ` · ${occVals[idx % occVals.length]}` : '';
                      const layerBg = canvasLayer === 'temp' ? 'background:rgba(245,158,11,0.16); border-color:rgba(217,119,6,0.45);' : canvasLayer === 'occupancy' ? 'background:rgba(46,148,97,0.14); border-color:rgba(46,148,97,0.42);' : '';
                      return `
                        <button type="button" class="pacom-zone-hotspot ${isActive ? 'is-active' : ''}"
                          style="left:${box.left}%; top:${box.top}%; width:${box.width}%; height:${box.height}%; ${!isActive ? layerBg : ''}"
                          data-filter-zone="${escapeHtml(isActive ? 'all' : z.id)}"
                          title="${escapeHtml(z.name)}（点击筛选该功能区设备）">
                          <span class="pacom-zone-tag">${escapeHtml(z.name.replace(/^7F\s*/, ''))}${layerSuffix}</span>
                        </button>`;
                    })
                    .join('')}
                  ${devices
                    .filter((d) => d.planPoint)
                    .map((d) => {
                      const hasActiveAlarm = alarms.some((a) => a.deviceId === d.id && a.status === 'active');
                      const focusAlarms = hudOpen && activeTab === 'alarms';
                      const isDimmed = (zoneFilter !== 'all' && d.logicalZoneId !== zoneFilter) || (focusAlarms && !hasActiveAlarm);
                      const alarmStyle = focusAlarms && hasActiveAlarm ? 'background:var(--pacom-status-critical);' : '';
                      const pinTopPct = d.category === 'gateway' ? Math.min(92, d.planPoint!.y * 100 + 5.5) : d.planPoint!.y * 100;
                      return `
                        <button type="button" class="pacom-pin ${d.id === selectedDeviceId && drawerOpen ? 'is-selected' : ''} ${d.connectivity === 'offline' ? 'pacom-pin--offline' : ''} ${isDimmed ? 'pacom-pin--dimmed' : ''}"
                          style="left:${(d.planPoint!.x * 100).toFixed(2)}%; top:${pinTopPct.toFixed(2)}%; ${alarmStyle}"
                          data-pin-device="${escapeHtml(d.id)}" title="${escapeHtml(d.name)}">
                          <span class="pacom-dot ${hasActiveAlarm ? 'pacom-dot--critical' : d.connectivity === 'online' ? 'pacom-dot--online' : 'pacom-dot--offline'}"></span>
                          <span>${escapeHtml(formatPinLabel(d))}</span>
                        </button>`;
                    })
                    .join('')}
                </div>
              </div>`
        }
      </div>
    `;
  }

  function renderDrawer(): string {
    if (scope.level !== 'floor' || !drawerOpen) return '';
    const device = devices.find((d) => d.id === selectedDeviceId);
    if (!device) return '';

    const isLighting = device.category === 'lighting';
    const isHvac = device.category === 'hvac';
    const dimmingVal = Number(device.telemetry.dimming?.value ?? 50);
    const setpointVal = Number(device.telemetry.setpoint?.value ?? 24);
    const isOverridden = overriddenDeviceIds.has(device.id);
    const deviceAlarms = alarms.filter((a) => a.deviceId === device.id && a.status === 'active');
    const deviceWos = workOrders.filter((w) => w.deviceId === device.id && w.status !== 'closed');
    const deviceDocs = isHvac
      ? [
          { name: 'E7F_暖通空调与末端竣工图_v2.3.pdf', tag: '竣工图纸' },
          { name: 'FCU-01_风机盘管维保与排障手册.pdf', tag: '维保手册' },
        ]
      : isLighting
        ? [{ name: 'E7F_强电照明与DALI回路拓扑.pdf', tag: '回路图纸' }]
        : [{ name: 'E7F_BACnet_Modbus_点位映射表.xlsx', tag: '点位台账' }];

    const telemetryPairs: Array<{ label: string; value: string }> = isLighting
      ? [
          { label: '当前开关', value: dimmingVal > 0 ? '开启' : '关闭' },
          { label: '当前亮度', value: `${dimmingVal}%` },
          { label: '实时功率', value: dimmingVal > 0 ? `${Math.round(dimmingVal * 1.4)} W` : '0 W' },
          { label: '运行模式', value: isOverridden ? '人工覆盖' : '自动策略' },
        ]
      : isHvac
        ? [
            { label: '室内温度', value: `${device.telemetry.temp?.value ?? '23.8'}°C` },
            { label: '设定温度', value: `${setpointVal.toFixed(1)}°C` },
            { label: '运行工况', value: device.connectivity === 'online' ? '制冷运行' : '通信离线' },
            { label: '控制模式', value: isOverridden ? '人工覆盖' : '自动策略' },
          ]
        : device.category === 'sensor'
          ? [
              { label: '实时温度', value: `${device.telemetry.temp?.value ?? '23.4'}°C` },
              { label: '相对湿度', value: `${device.telemetry.humidity?.value ?? '52'}%` },
              { label: 'CO₂ 浓度', value: `${device.telemetry.co2?.value ?? '485'} ppm` },
              { label: '采集状态', value: device.connectivity === 'online' ? '正常上报' : '断流异常' },
            ]
          : [
              { label: '通信状态', value: device.connectivity === 'online' ? '已连通' : '离线' },
              { label: '通信协议', value: device.hardwareBinding?.protocol.toUpperCase() ?? 'BACNET' },
              { label: '网络地址', value: device.hardwareBinding?.networkAddress ?? '-' },
              { label: '心跳延迟', value: device.connectivity === 'online' ? '18 ms' : '--' },
            ];

    return `
      <aside class="pacom-drawer" aria-label="设备详情与控制">
        <div class="pacom-drawer-head">
          <div style="min-width:0;">
            <h2 class="pacom-drawer-title">${escapeHtml(device.name)}</h2>
            <div class="pacom-row-sub">${escapeHtml(getZoneName(device.logicalZoneId))} · ${escapeHtml(CATEGORY_LABELS[device.category])}</div>
          </div>
          <div style="display:flex; align-items:center; gap:6px;">
            <span class="pacom-badge ${device.connectivity === 'online' ? 'pacom-badge--online' : 'pacom-badge--critical'}">
              ${device.connectivity === 'online' ? '在线' : '离线'}
            </span>
            <button type="button" class="pacom-drawer-close" data-role="close-drawer" aria-label="关闭设备详情" title="关闭（Esc）">
              ${renderIcon('x', 16)}
            </button>
          </div>
        </div>

        <div class="pacom-tabs" role="tablist" aria-label="设备档案分页" style="width:100%; justify-content:space-between;">
          <button type="button" class="pacom-tab" style="flex:1; justify-content:center; font-size:12px;" role="tab" aria-selected="${drawerTab === 'control'}" data-drawer-tab="control">控制与工况</button>
          <button type="button" class="pacom-tab" style="flex:1; justify-content:center; font-size:12px;" role="tab" aria-selected="${drawerTab === 'trend'}" data-drawer-tab="trend">趋势与告警${deviceAlarms.length > 0 ? ` (${deviceAlarms.length})` : ''}</button>
          <button type="button" class="pacom-tab" style="flex:1; justify-content:center; font-size:12px;" role="tab" aria-selected="${drawerTab === 'profile'}" data-drawer-tab="profile">档案与图纸</button>
        </div>

        ${
          drawerTab === 'control'
            ? `
            <div style="display:grid; grid-template-columns:repeat(2,1fr); gap:6px;">
              ${telemetryPairs
                .map(
                  (item) => `
                  <div class="pacom-control-box" style="padding:8px 10px; gap:2px;">
                    <span class="pacom-row-sub">${item.label}</span>
                    <strong style="font-size:13px; font-weight:500;">${escapeHtml(item.value)}</strong>
                  </div>`
                )
                .join('')}
            </div>

            ${
              isHvac
                ? `
                <div class="lov-schematic-strip" aria-label="暖通工况简图">
                  <div style="display:flex; justify-content:space-between; align-items:center; font-size:12px;">
                    <span style="font-weight:500; color:var(--pacom-text-primary);">实时气流工况示意</span>
                    <span class="pacom-row-sub">${device.connectivity === 'online' ? '制冷运转' : '通信离线'}</span>
                  </div>
                  <svg viewBox="0 0 300 44" style="width:100%; height:44px; display:block;">
                    <line x1="10" y1="22" x2="290" y2="22" stroke="oklch(85.12% 0 107)" stroke-width="2" stroke-dasharray="4 3" />
                    <rect x="12" y="10" width="46" height="24" rx="6" fill="var(--pacom-surface-card)" stroke="oklch(82% 0 107)" />
                    <text x="35" y="25" text-anchor="middle" font-size="10" fill="var(--pacom-text-secondary)">回风 ${escapeHtml(device.telemetry.temp?.value ?? '23.8')}°</text>
                    <rect x="80" y="8" width="54" height="28" rx="6" fill="${device.connectivity === 'online' ? 'oklch(95% 0.04 145)' : 'var(--pacom-surface-recessed)'}" stroke="${device.connectivity === 'online' ? 'var(--pacom-status-online)' : 'oklch(82% 0 107)'}" />
                    <text x="107" y="25" text-anchor="middle" font-size="10" fill="var(--pacom-text-primary)">${device.connectivity === 'online' ? '冷盘管 开' : '盘管 离线'}</text>
                    <circle cx="172" cy="22" r="13" fill="var(--pacom-surface-card)" stroke="${device.connectivity === 'online' ? 'var(--pacom-accent-solid)' : 'oklch(75% 0 107)'}" stroke-width="1.5" />
                    <text x="172" y="25" text-anchor="middle" font-size="10" fill="var(--pacom-text-primary)">风机</text>
                    <rect x="208" y="10" width="78" height="24" rx="6" fill="var(--pacom-surface-card)" stroke="var(--pacom-accent-solid)" />
                    <text x="247" y="25" text-anchor="middle" font-size="10" fill="var(--pacom-text-primary)">送风 ${setpointVal.toFixed(1)}°C</text>
                  </svg>
                </div>`
                : ''
            }

            ${
              isLighting || isHvac
                ? `
                <div class="pacom-control-box">
                  <div style="display:flex; justify-content:space-between; align-items:center;">
                    <span style="font-weight:500; font-size:13px;">实时控制（网关逐设备回读）</span>
                    ${
                      isOverridden && canControl
                        ? `<button type="button" class="pacom-btn pacom-btn--ghost" style="height:24px; padding:0 8px; font-size:12px;" data-release-override="${escapeHtml(device.id)}">恢复自动策略</button>`
                        : !canControl
                          ? `<span class="pacom-badge pacom-badge--neutral">只读</span>`
                          : ''
                    }
                  </div>
                  ${
                    device.connectivity === 'offline'
                      ? `<div class="pacom-row-sub" style="color:var(--pacom-status-warning);">当前设备离线，下发后将返回网关回读超时回执。</div>`
                      : ''
                  }
                  ${
                    isLighting
                      ? `
                      <div style="display:flex; gap:6px;">
                        <button type="button" class="pacom-btn" data-ctrl-cmd="lighting.power" data-ctrl-val="true" ${canControl ? '' : 'disabled'}>开灯</button>
                        <button type="button" class="pacom-btn" data-ctrl-cmd="lighting.power" data-ctrl-val="false" ${canControl ? '' : 'disabled'}>关灯</button>
                      </div>
                      <label style="font-size:12px; display:flex; flex-direction:column; gap:4px;">
                        亮度目标：<strong>${dimmingVal}%</strong>
                        <input type="range" min="0" max="100" step="10" value="${dimmingVal}" data-ctrl-slider="lighting.dimming" ${canControl ? '' : 'disabled'} />
                      </label>`
                      : `
                      <div style="display:flex; gap:6px;">
                        <button type="button" class="pacom-btn" data-ctrl-cmd="hvac.power" data-ctrl-val="true" ${canControl ? '' : 'disabled'}>开机</button>
                        <button type="button" class="pacom-btn" data-ctrl-cmd="hvac.power" data-ctrl-val="false" ${canControl ? '' : 'disabled'}>关机</button>
                      </div>
                      <div style="display:flex; align-items:center; gap:8px;">
                        <span style="font-size:12px;">设定温度：</span>
                        <button type="button" class="pacom-btn" data-ctrl-cmd="hvac.setpoint" data-ctrl-val="${setpointVal - 0.5}" ${canControl ? '' : 'disabled'}>-0.5°C</button>
                        <strong>${setpointVal.toFixed(1)}°C</strong>
                        <button type="button" class="pacom-btn" data-ctrl-cmd="hvac.setpoint" data-ctrl-val="${setpointVal + 0.5}" ${canControl ? '' : 'disabled'}>+0.5°C</button>
                      </div>`
                  }
                </div>`
                : ''
            }

            ${
              activeBatch
                ? `
                <div class="pacom-control-box">
                  <div style="font-size:12px; font-weight:500;">最近批次：<code>${escapeHtml(activeBatch.batchId)}</code></div>
                  <div class="pacom-receipt-list">
                    ${activeBatch.receipts
                      .map((r) => {
                        const meta = RECEIPT_LABELS[r.status] ?? { text: r.status, badge: 'pacom-badge--neutral' };
                        return `
                          <div class="pacom-receipt-item">
                            <div>
                              <div><strong>${escapeHtml(r.deviceId)}</strong> · ${escapeHtml(r.command)} → ${escapeHtml(r.targetValue)}</div>
                              ${r.errorMessage ? `<div style="color:var(--pacom-status-critical);">${escapeHtml(r.errorMessage)}</div>` : ''}
                            </div>
                            <span class="pacom-badge ${meta.badge}">${meta.text}</span>
                          </div>`;
                      })
                      .join('')}
                  </div>
                </div>`
                : ''
            }`
            : drawerTab === 'trend'
              ? `
              <div class="pacom-control-box" style="padding:10px 12px; gap:6px;">
                <div style="display:flex; justify-content:space-between; align-items:center;">
                  <span class="pacom-row-sub">近 24 小时趋势（${isLighting ? '亮度 %' : isHvac ? '温度 °C' : device.category === 'sensor' ? '室内温度 °C' : '链路延迟 ms'}）</span>
                  <button type="button" class="pacom-btn pacom-btn--ghost" style="height:22px; padding:0 6px; font-size:12px;" data-go-timeseries="${escapeHtml(device.id)}">查看完整时序 →</button>
                </div>
                <svg viewBox="0 0 280 48" style="width:100%; height:48px; display:block;">
                  <line x1="0" y1="24" x2="280" y2="24" stroke="oklch(82% 0 107)" stroke-dasharray="3 3" />
                  <polyline fill="none" stroke="${device.connectivity === 'online' ? 'var(--pacom-accent-solid)' : 'var(--pacom-status-offline)'}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="${isLighting ? '0,38 40,38 80,16 120,12 160,14 200,20 240,14 280,16' : isHvac ? '0,28 40,30 80,25 120,20 160,18 200,22 240,24 280,20' : '0,24 40,25 80,23 120,21 160,20 200,22 240,21 280,22'}" />
                </svg>
              </div>

              <div class="pacom-control-box" style="gap:6px;">
                <div style="display:flex; justify-content:space-between; align-items:center;">
                  <span style="font-size:12px; font-weight:500;">本机活跃告警与未结工单</span>
                  <button type="button" class="pacom-btn pacom-btn--ghost" style="height:22px; padding:0 6px; font-size:12px;" data-go-alarms="1">告警中心 →</button>
                </div>
                ${
                  deviceAlarms.length === 0 && deviceWos.length === 0
                    ? `<div class="pacom-row-sub">当前设备运行平稳，无未处理告警或工单。</div>`
                    : `${deviceAlarms
                        .map(
                          (a) => `
                          <button type="button" class="pacom-receipt-item" style="border:0; width:100%; text-align:left; cursor:pointer;" data-go-alarm-id="${escapeHtml(a.id)}">
                            <span style="font-size:12px; font-weight:500; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(a.title)}</span>
                            <span class="pacom-badge pacom-badge--warning">去诊断 →</span>
                          </button>`
                        )
                        .join('')}${deviceWos
                        .map(
                          (w) => `
                          <button type="button" class="pacom-receipt-item" style="border:0; width:100%; text-align:left; cursor:pointer;" data-go-wo-id="${escapeHtml(w.id)}">
                            <span style="font-size:12px; font-weight:500; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(w.title)}</span>
                            <span class="pacom-badge pacom-badge--accent">查看工单 →</span>
                          </button>`
                        )
                        .join('')}`
                }
              </div>`
              : `
              <div class="pacom-control-box" style="gap:6px;">
                <span style="font-size:12px; font-weight:500;">上下游拓扑关系（Twin Relationships）</span>
                <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap; font-size:12px;">
                  <span class="pacom-badge pacom-badge--neutral">E7F 主控网关-01</span>
                  <span class="pacom-row-sub">→</span>
                  <span class="pacom-badge pacom-badge--accent">${escapeHtml(formatPinLabel(device))}</span>
                  <span class="pacom-row-sub">→</span>
                  <span class="pacom-badge pacom-badge--online">${escapeHtml(getZoneName(device.logicalZoneId).replace(/^7F\s*/, ''))}</span>
                </div>
              </div>

              <div class="pacom-control-box" style="gap:6px;">
                <span style="font-size:12px; font-weight:500;">关联竣工图纸与设备手册</span>
                ${drawerDocNotice ? `<div class="pacom-info-banner">${escapeHtml(drawerDocNotice)}</div>` : ''}
                ${deviceDocs
                  .map(
                    (doc) => `
                    <div class="pacom-receipt-item">
                      <span style="font-size:12px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${escapeHtml(doc.name)}">${escapeHtml(doc.name)}</span>
                      <button type="button" class="pacom-btn" style="height:24px; padding:0 8px; font-size:11px;" data-drawer-doc="${escapeHtml(doc.name)}">查阅</button>
                    </div>`
                  )
                  .join('')}
              </div>

              <details class="lov-tech-details" open>
                <summary><span>技术标识与硬件绑定</span>${renderIcon('chevron-down', 12)}</summary>
                <div class="pacom-kv-grid">
                  <span class="pacom-kv-label">设备编号</span><span><code>${escapeHtml(device.id)}</code> · v${device.version}</span>
                  <span class="pacom-kv-label">图上点位</span><span>${device.planPoint ? `x=${device.planPoint.x.toFixed(2)}, y=${device.planPoint.y.toFixed(2)} (图 v${device.planPoint.planVersion})` : '未标点'}</span>
                  <span class="pacom-kv-label">物理安装</span><span>${device.physicalInstalled ? '现场已确认' : '待现场复核'}</span>
                  <span class="pacom-kv-label">硬件绑定</span><span>${device.hardwareBinding ? `${device.hardwareBinding.protocol.toUpperCase()} · ${device.hardwareBinding.networkAddress}` : '未绑定'}</span>
                </div>
              </details>`
        }
      </aside>
    `;
  }

  function renderBriefingPopover(onlineCount: number, activeAlarmCount: number, sensorTemp: unknown): string {
    if (!briefingOpen) return '';
    const offlineCount = Math.max(0, devices.length - onlineCount);
    const isWeek = briefingPeriod === 'week';
    const topBriefAlarms = alarms.filter((a) => a.status === 'active').slice(0, 2);
    return `
      <div class="lov-briefing-pop" style="width:420px; top:48px; right:20px;" role="dialog" aria-label="运行简报" data-role="briefing-pop">
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
          <div>
            <strong style="font-size:14px; font-weight:500;">E7F ${isWeek ? '本周运行汇总简报' : '今日值班晨报'}</strong>
            <div class="pacom-row-sub">广州 26°C 多云 · 湿度 64% · 舒适度达标 96.2%</div>
          </div>
          <div style="display:flex; align-items:center; gap:6px;">
            <div class="pacom-tabs">
              <button type="button" class="pacom-tab" style="height:24px; padding:0 8px; font-size:12px;" aria-selected="${!isWeek}" data-briefing-period="today">今日值班</button>
              <button type="button" class="pacom-tab" style="height:24px; padding:0 8px; font-size:12px;" aria-selected="${isWeek}" data-briefing-period="week">本周汇总</button>
            </div>
            <button type="button" class="pacom-drawer-close" data-toggle-briefing="1" aria-label="关闭简报">${renderIcon('x', 16)}</button>
          </div>
        </div>
        <div style="display:grid; grid-template-columns:repeat(2,1fr); gap:6px;">
          <div class="pacom-control-box" style="padding:8px 10px; gap:2px;"><span class="pacom-row-sub">${isWeek ? '本周累计节能' : '昨日能耗偏差'}</span><strong style="color:var(--pacom-status-online);">${isWeek ? '-7.1%（省 ¥342）' : '-6.4%（省 ¥48）'}</strong></div>
          <div class="pacom-control-box" style="padding:8px 10px; gap:2px;"><span class="pacom-row-sub">均温 / 在线率</span><strong>${escapeHtml(sensorTemp)}°C · ${onlineCount}/${devices.length}</strong></div>
          <div class="pacom-control-box" style="padding:8px 10px; gap:2px;"><span class="pacom-row-sub">待处理告警 / 离线</span><strong style="color:var(--pacom-status-warning);">${activeAlarmCount} 告警 · ${offlineCount} 离线</strong></div>
          <div class="pacom-control-box" style="padding:8px 10px; gap:2px;"><span class="pacom-row-sub">人工覆盖 / 未结工单</span><strong>${Math.max(1, overriddenDeviceIds.size)} 覆盖 · ${workOrders.filter((w) => w.status !== 'closed').length} 工单</strong></div>
        </div>
        ${
          topBriefAlarms.length > 0
            ? `<div style="display:flex; flex-direction:column; gap:5px;">
                <span class="pacom-row-sub">优先关注事项（点击直达）</span>
                ${topBriefAlarms
                  .map(
                    (a) => `
                    <button type="button" class="pacom-receipt-item" style="border:0; width:100%; text-align:left; cursor:pointer;" data-go-alarm-id="${escapeHtml(a.id)}">
                      <span style="font-size:12px; font-weight:500; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(a.title)}</span>
                      <span class="pacom-badge pacom-badge--warning">去处置 →</span>
                    </button>`
                  )
                  .join('')}
              </div>`
            : ''
        }
        <div style="display:flex; justify-content:space-between; gap:8px;">
          <button type="button" class="pacom-btn" data-export-briefing="1">导出简报 (.txt)</button>
          <button type="button" class="pacom-btn pacom-btn--primary" data-go-alarms="1">进入告警中心 →</button>
        </div>
      </div>
    `;
  }

  function render(): void {
    const activeAlarmCount = alarms.filter((a) => a.status === 'active').length;
    const onlineCount = devices.filter((d) => d.connectivity === 'online').length;
    const sensorTemp = devices.find((d) => d.category === 'sensor')?.telemetry.temp?.value ?? '23.4';

    root.innerHTML = `
      <div class="pacom-shell" style="position:relative;">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <div class="pacom-title-group">
              <h1 class="pacom-title">空间总览</h1>
              ${renderSpacePathControl({ tree, session, scope, activeAlarmCount, isOpen: spacePopOpen, searchKeyword: spaceSearch })}
            </div>

            <div class="pacom-header-meta" style="flex-shrink:0;">
              ${
                !floorError
                  ? `<button type="button" class="pacom-pulse-btn" data-toggle-briefing="1" aria-expanded="${briefingOpen}" title="点击查看今日运行简报">
                      <span class="pacom-dot pacom-dot--online"></span>
                      <span>${onlineCount}/${devices.length} 在线 · ${escapeHtml(sensorTemp)}°C · 简报</span>
                      <span style="display:inline-flex; color:var(--pacom-text-secondary);">${CHEVRON_DOWN_SVG}</span>
                    </button>`
                  : isDemo
                    ? `<span class="pacom-badge pacom-badge--neutral"><span class="pacom-dot pacom-dot--offline"></span>演示模式</span>`
                    : `<span class="pacom-badge pacom-badge--online"><span class="pacom-dot pacom-dot--online"></span>实时连接</span>`
              }
            </div>
          </div>
        </header>

        ${renderBriefingPopover(onlineCount, activeAlarmCount, sensorTemp)}

        <main class="pacom-spatial-stage">
          ${renderFloatingHud(activeAlarmCount)}
          ${renderSpatialCanvas(onlineCount, activeAlarmCount)}
          ${renderElevationScrubber(activeAlarmCount)}
          ${renderBottomDock(onlineCount, activeAlarmCount)}
          ${renderDrawer()}
        </main>
      </div>
    `;

    bindEvents();
  }

  function bindEvents(): void {
    bindSpacePathControl(root, {
      onToggle: () => {
        spacePopOpen = !spacePopOpen;
        if (spacePopOpen) {
          briefingOpen = false;
          hudOpen = false;
        }
        render();
        if (spacePopOpen) {
          root.querySelector<HTMLInputElement>('[data-global-space-search]')?.focus();
        }
      },
      onSearch: (kw) => {
        spaceSearch = kw;
        render();
        const el = root.querySelector<HTMLInputElement>('[data-global-space-search]');
        if (el) {
          el.focus();
          el.setSelectionRange(kw.length, kw.length);
        }
      },
      onPick: (next) => {
        spacePopOpen = false;
        void setScope(next);
      },
    });

    root.querySelectorAll<HTMLElement>('[data-nav-scope]').forEach((el) => {
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        if (el.dataset.navScope) void setScope(parseScopeValue(el.dataset.navScope));
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-hud-tab]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const nextTab = btn.dataset.hudTab as ActiveTab;
        if (hudOpen && activeTab === nextTab) {
          hudOpen = false;
        } else {
          activeTab = nextTab;
          hudOpen = true;
          spacePopOpen = false;
          briefingOpen = false;
        }
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-toggle-hud]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        hudOpen = !hudOpen;
        if (hudOpen) {
          spacePopOpen = false;
          briefingOpen = false;
        }
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-close-hud]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        hudOpen = false;
        render();
      });
    });

    const searchEl = root.querySelector<HTMLInputElement>('[data-role="search"]');
    searchEl?.addEventListener('focus', () => {
      if (!hudOpen) {
        hudOpen = true;
        spacePopOpen = false;
        briefingOpen = false;
        renderPreservingFocus();
      }
    });
    searchEl?.addEventListener('input', (e) => {
      searchKeyword = (e.currentTarget as HTMLInputElement).value;
      hudOpen = true;
      renderPreservingFocus();
    });

    root.querySelector<HTMLSelectElement>('[data-role="category"]')?.addEventListener('change', (e) => {
      categoryFilter = (e.currentTarget as HTMLSelectElement).value;
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-filter-zone]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        zoneFilter = btn.dataset.filterZone ?? 'all';
        render();
      });
    });

    root.querySelectorAll<HTMLElement>('[data-select-device]').forEach((row) => {
      row.addEventListener('click', (e) => {
        if ((e.target as HTMLElement).tagName === 'INPUT') return;
        selectedDeviceId = row.dataset.selectDevice ?? null;
        drawerOpen = true;
        render();
      });
    });

    root.querySelectorAll<HTMLInputElement>('[data-check-device]').forEach((chk) => {
      chk.addEventListener('change', () => {
        const id = chk.dataset.checkDevice;
        if (!id) return;
        if (chk.checked) checkedDeviceIds.add(id);
        else checkedDeviceIds.delete(id);
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-pin-device]').forEach((pin) => {
      pin.addEventListener('click', (e) => {
        e.stopPropagation();
        selectedDeviceId = pin.dataset.pinDevice ?? null;
        drawerOpen = true;
        spacePopOpen = false;
        briefingOpen = false;
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-role="close-drawer"]')?.addEventListener('click', () => {
      drawerOpen = false;
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-drawer-tab]').forEach((btn) => {
      btn.addEventListener('click', () => {
        drawerTab = (btn.dataset.drawerTab as 'control' | 'trend' | 'profile') ?? 'control';
        drawerDocNotice = '';
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-drawer-doc]').forEach((btn) => {
      btn.addEventListener('click', () => {
        drawerDocNotice = `已调阅「${btn.dataset.drawerDoc ?? ''}」（完整工程文档库见「系统部署 → 楼层与功能区」）。`;
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-briefing-period]').forEach((btn) => {
      btn.addEventListener('click', () => {
        briefingPeriod = (btn.dataset.briefingPeriod as 'today' | 'week') ?? 'today';
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-go-alarm-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.goAlarmId ?? '';
        window.location.hash = id ? `#alarms?alarm=${encodeURIComponent(id)}` : '#alarms';
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-go-wo-id]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.goWoId ?? '';
        window.location.hash = id ? `#alarms?wo=${encodeURIComponent(id)}` : '#alarms';
      });
    });

    root.querySelector<HTMLButtonElement>('[data-release-override]')?.addEventListener('click', (e) => {
      const id = (e.currentTarget as HTMLButtonElement).dataset.releaseOverride;
      if (id) {
        overriddenDeviceIds.delete(id);
        render();
      }
    });

    root.querySelectorAll<HTMLButtonElement>('[data-zone-power]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const zid = btn.dataset.zonePower;
        const on = btn.dataset.zoneVal === 'true';
        if (!zid) return;
        const lightIds = devices.filter((d) => d.logicalZoneId === zid && d.category === 'lighting').map((d) => d.id);
        const hvacIds = devices.filter((d) => d.logicalZoneId === zid && d.category === 'hvac').map((d) => d.id);
        if (lightIds.length) void dispatchCommand(lightIds, 'lighting.power', on);
        else if (hvacIds.length) void dispatchCommand(hvacIds, 'hvac.power', on);
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-locate-device]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.dataset.locateDevice;
        if (!id) return;
        selectedDeviceId = id;
        drawerOpen = true;
        hudOpen = false;
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-go-alarms]').forEach((btn) => {
      btn.addEventListener('click', () => {
        window.location.hash = '#alarms';
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-go-analysis]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const cat = btn.dataset.goAnalysis || 'energy';
        window.location.hash = `#analysis?cat=${encodeURIComponent(cat)}`;
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-go-timeseries]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const devId = btn.dataset.goTimeseries || '';
        window.location.hash = `#analysis?tab=timeseries&device=${encodeURIComponent(devId)}`;
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-toggle-briefing]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        briefingOpen = !briefingOpen;
        if (briefingOpen) {
          spacePopOpen = false;
          hudOpen = false;
        }
        render();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-export-briefing]')?.addEventListener('click', () => {
      const onlineCount = devices.filter((d) => d.connectivity === 'online').length;
      const activeAlarmCount = alarms.filter((a) => a.status === 'active').length;
      const text = [
        'PACOM Station 今日运行简报（广实2号园 E栋 7F）',
        `生成时间：${new Date().toLocaleString('zh-CN')}`,
        `室外气象：26°C 多云 · 湿度 64%`,
        `昨日能耗偏差：-6.4%（预计节省 ¥48）`,
        `设备在线：${onlineCount}/${devices.length}（离线 ${devices.length - onlineCount} 台）`,
        `待处理告警：${activeAlarmCount} 条`,
        `人工覆盖中：${overriddenDeviceIds.size} 台`,
      ].join('\n');
      const blob = new Blob([text], { type: 'text/plain;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'pacom-daily-briefing.txt';
      a.click();
      URL.revokeObjectURL(url);
    });

    root.querySelectorAll<HTMLButtonElement>('[data-ctrl-cmd]').forEach((btn) => {
      btn.addEventListener('click', () => {
        if (!selectedDeviceId || !btn.dataset.ctrlCmd) return;
        const raw = btn.dataset.ctrlVal ?? '';
        const val = raw === 'true' ? true : raw === 'false' ? false : Number(raw);
        void dispatchCommand([selectedDeviceId], btn.dataset.ctrlCmd as ControlCommandType, val);
      });
    });

    root.querySelector<HTMLInputElement>('[data-ctrl-slider]')?.addEventListener('change', (e) => {
      const input = e.currentTarget as HTMLInputElement;
      if (!selectedDeviceId || !input.dataset.ctrlSlider) return;
      void dispatchCommand([selectedDeviceId], input.dataset.ctrlSlider as ControlCommandType, Number(input.value));
    });

    root.querySelectorAll<HTMLButtonElement>('[data-batch-cmd]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const ids = Array.from(checkedDeviceIds);
        const raw = btn.dataset.batchVal ?? '';
        const val = raw === 'true' ? true : raw === 'false' ? false : raw;
        void dispatchCommand(ids, btn.dataset.batchCmd as ControlCommandType, val);
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-ack-alarm]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (!btn.dataset.ackAlarm || scope.level !== 'floor' || !canManageAlarms) return;
        await adapter.acknowledgeAlarm(btn.dataset.ackAlarm, '首页快速确认');
        alarms = await adapter.listAlarms(scope.floorId);
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-canvas-layer]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const next = btn.dataset.canvasLayer as 'devices' | 'temp' | 'occupancy' | undefined;
        if (next) {
          canvasLayer = next;
          render();
        }
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-zoom]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const action = btn.dataset.zoom;
        if (action === 'in') zoom = Math.min(2.6, Number((zoom + 0.2).toFixed(2)));
        else if (action === 'out') zoom = Math.max(0.6, Number((zoom - 0.2).toFixed(2)));
        else {
          zoom = 1;
          panX = 0;
          panY = 0;
        }
        applyViewportTransform();
      });
    });

    // 右侧建筑标高尺支持滚轮上下切层
    const scrubber = root.querySelector<HTMLElement>('[data-role="elevation-scrubber"]');
    scrubber?.addEventListener(
      'wheel',
      (e) => {
        e.preventDefault();
        const s = scope;
        if (s.level !== 'building' && s.level !== 'floor') return;
        const floors = getBuildingFloors(s.buildingId);
        const seq: HomeScope[] = [
          ...(canViewBuilding ? [{ level: 'building' as const, projectId: s.projectId, buildingId: s.buildingId }] : []),
          ...floors.map((f) => ({ level: 'floor' as const, projectId: s.projectId, buildingId: s.buildingId, floorId: f.id })),
        ];
        const curIdx = seq.findIndex((item) =>
          item.level === 'building'
            ? s.level === 'building'
            : item.level === 'floor' && s.level === 'floor' && item.floorId === s.floorId
        );
        if (curIdx < 0) return;
        const nextIdx = Math.max(0, Math.min(seq.length - 1, curIdx + (e.deltaY > 0 ? 1 : -1)));
        if (nextIdx !== curIdx && seq[nextIdx]) void setScope(seq[nextIdx]!);
      },
      { passive: false }
    );

    /* 画布真实拖动平移 + 滚轮平滑缩放 + 双击复位 + 点击空白收起弹层 */
    const canvasStage = root.querySelector<HTMLElement>('[data-role="canvas-stage"]');
    if (canvasStage && !floorError) {
      let dragging = false;
      let moved = false;
      let startX = 0;
      let startY = 0;
      let originPanX = 0;
      let originPanY = 0;

      canvasStage.addEventListener('pointerdown', (e) => {
        const target = e.target as HTMLElement | null;
        if (target?.closest('button, input, select, .pacom-drawer, .pacom-hud-search-wrap')) return;
        dragging = true;
        moved = false;
        startX = e.clientX;
        startY = e.clientY;
        originPanX = panX;
        originPanY = panY;
        canvasStage.classList.add('is-panning');
        canvasStage.setPointerCapture?.(e.pointerId);
      });

      canvasStage.addEventListener('pointermove', (e) => {
        if (!dragging) return;
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) moved = true;
        panX = originPanX + dx;
        panY = originPanY + dy;
        applyViewportTransform();
      });

      const endPan = () => {
        if (!dragging) return;
        dragging = false;
        canvasStage.classList.remove('is-panning');
        if (!moved && (hudOpen || spacePopOpen || briefingOpen)) {
          hudOpen = false;
          spacePopOpen = false;
          briefingOpen = false;
          render();
        }
      };
      canvasStage.addEventListener('pointerup', endPan);
      canvasStage.addEventListener('pointercancel', endPan);

      canvasStage.addEventListener(
        'wheel',
        (e) => {
          e.preventDefault();
          const delta = e.deltaY < 0 ? 0.12 : -0.12;
          zoom = Math.max(0.6, Math.min(2.6, Number((zoom + delta).toFixed(2))));
          applyViewportTransform();
        },
        { passive: false }
      );

      canvasStage.addEventListener('dblclick', (e) => {
        const target = e.target as HTMLElement | null;
        if (target?.closest('button')) return;
        zoom = 1;
        panX = 0;
        panY = 0;
        applyViewportTransform();
      });
    } else {
      root.querySelector<HTMLElement>('.pacom-spatial-stage')?.addEventListener('click', (e) => {
        const target = e.target as HTMLElement | null;
        if (target?.closest('button, input, select, .pacom-hud-search-wrap, .pacom-space-popover, .lov-briefing-pop')) return;
        if (hudOpen || spacePopOpen || briefingOpen) {
          hudOpen = false;
          spacePopOpen = false;
          briefingOpen = false;
          render();
        }
      });
    }
  }

  // Esc 快捷键收起当前打开的弹层/抽屉
  root.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    if (spacePopOpen || briefingOpen || hudOpen || drawerOpen) {
      spacePopOpen = false;
      briefingOpen = false;
      hudOpen = false;
      drawerOpen = false;
      render();
    }
  });

  await setScope(scope, true);
}
